import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        int[][] square = new int[n][n];

        int zeroRow = -1;
        int zeroCol = -1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                square[i][j] = sc.nextInt();
                if (square[i][j] == 0) {
                    zeroRow = i;
                    zeroCol = j;
                }
            }
        }

        int magicSum = 0;

        for (int i = 0; i < n; i++) {
            if (i != zeroRow) {
                int sum = 0;
                for (int j = 0; j < n; j++) {
                    sum += square[i][j];
                }
                magicSum = sum;
                break;
            }
        }

        int zeroRowSum = 0;
        for (int j = 0; j < n; j++) {
            zeroRowSum += square[zeroRow][j];
        }

        int missingValue = magicSum - zeroRowSum;

        System.out.println(missingValue);
        System.out.println(zeroRow + 1);
        System.out.println(zeroCol + 1);
    }
}
